from itertools import permutations
from typing import Sequence

Matrix = Sequence[Sequence[int]]

def leibniz_det(a: Matrix, n: int) -> int:
    """Exact determinant of an n x n integer matrix via the Leibniz sum."""
    total = 0
    for perm in permutations(range(n)):
        sign = 1
        for i in range(n):
            for j in range(i + 1, n):
                if perm[i] > perm[j]:
                    sign = -sign
        prod = 1
        for i in range(n):
            prod *= a[i][perm[i]]
        total += sign * prod
    return total

