            prod *= a[i][p[i]]
        total += s * prod
    return total

def max_det_bounded(c: int) -> Tuple[int, Matrix]:
    """Brute-force the maximal determinant D(c) over all c-admissible 4x4
    matrices. Feasible only for very small c; used to validate D(c) = 16 c^4."""
    from itertools import product
    values = range(-c, c + 1)
    best_det = None
    best_mat: Matrix = ()
    for flat in product(values, repeat=16):
        m = tuple(tuple(flat[4 * i + j] for j in range(4)) for i in range(4))
        d = det4(m)
        if best_det is None or d > best_det:
            best_det, best_mat = d, m
    return best_det, best_mat

