from itertools import permutations
from typing import Sequence, Tuple

Matrix = Sequence[Sequence[int]]

def det4(a: Matrix) -> int:
    total = 0
    for p in permutations(range(4)):
        s = 1
        for i in range(4):
            for j in range(i + 1, 4):
                if p[i] > p[j]:
                    s = -s
        prod = 1
        for i in range(4):
            prod *= a[i][p[i]]
        total += s * prod
    return total

def factor_out_two(sign_matrix: Matrix) -> Tuple[int, Matrix]:
    """Given a 4x4 +/-1 matrix, subtract row 0 from rows 1..3, factor 2 out of
    each reduced row, and return (8, reduced integer matrix M') such that
    det(sign_matrix) = 8 * det(M'). Constructive proof of 8 | det."""
    r0 = sign_matrix[0]
    reduced = [list(r0)]
    for i in range(1, 4):
        reduced.append([(sign_matrix[i][j] - r0[j]) // 2 for j in range(4)])
    return 8, tuple(tuple(row) for row in reduced)

def verify_divisibility(sign_matrix: Matrix) -> bool:
    factor, mprime = factor_out_two(sign_matrix)
    return det4(sign_matrix) == factor * det4(mprime)
